from collections import Counter

def get_most_assigned_bug_person(repo_name):
    assignee_counts = Counter()
    offset = 0
    limit = 50

    while True:
        # Fetch open bug issues
        result = list_issues(repo=repo_name, state='open', label='bug', limit=limit, offset=offset)
        issues = result.get('items', [])

        if not issues:
            break

        for issue in issues:
            assignee_id = issue.get('assignee')
            if assignee_id:
                assignee_counts[assignee_id] += 1

        if len(issues) < limit:
            break
        offset += limit

    if not assignee_counts:
        return None

    # Get the most frequent assignee ID
    most_common_id, count = assignee_counts.most_common(1)[0]

    # Lookup the name
    user_info = lookup_user(user_id=most_common_id)
    return user_info.get('name')

