def get_most_assigned_bug_person(repo):
    assignee_counts = {}
    offset = 0
    limit = 50

    while True:
        issues_data = list_issues(repo=repo, state='open', label='bug', limit=limit, offset=offset)
        items = issues_data.get('items', [])

        if not items:
            break

        for issue in items:
            assignee_id = issue.get('assignee')
            if assignee_id:
                assignee_counts[assignee_id] = assignee_counts.get(assignee_id, 0) + 1

        # Check if we've reached the end
        if len(items) < limit:
            break
        offset += limit

    if not assignee_counts:
        return None

    # Find the assignee with the most issues
    max_count = -1
    top_assignee_id = None
    for uid, count in assignee_counts.items():
        if count > max_count:
            max_count = count
            top_assignee_id = uid

    if top_assignee_id:
        user_info = lookup_user(user_id=top_assignee_id)
