def update_fjord_tickets():
    offset = 0
    limit = 50
    updated_count = 0

    while True:
        # We need to find 'open' tickets with 'low' priority for customer 'Fjord'
        # list_tickets allows filtering by status and priority
        results = list_tickets(status='open', priority='low', limit=limit, offset=offset)

        items = results.get('items', [])
        if not items:
            break

        for ticket in items:
            if ticket.get('customer') == 'Fjord':
                # Update priority to 'high'
                success = triage_ticket(ticket['id'], 'high')
                if success:
                    updated_count += 1

        # Check if we've reached the end
        if offset + len(items) >= results.get('total', 0):
            break

        offset += limit

    print(f"Updated {updated_count} tickets.")

